#include <algorithm>
#include <functional>
#include <string>
#include <vector>

std::vector<std::pair<int,int>> free_slots(int limit, std::vector<std::pair<int,int>> busy) {
    if (limit <= 0) return {};

    std::sort(busy.begin(), busy.end(), [](const auto& a, const auto& b) {
        return a.first < b.first;
    });

    std::vector<std::pair<int,int>> result;
    int start = 0;
    int end = 0;

    while (start < busy.size()) {
        if (end == busy[start].first) {
            end++;
        } else {
            result.push_back({start, end});
            start = end;
        }
    }

    if (start < busy.size()) {
        result.push_back({start, busy.size()});
    }

    return result;
}

